  '70923ac3df0fbb0b01c4ac3e0304ee4b95e3ca91a392a163bf95ca931407820e':
    "INSERT INTO agent_attribute_proposal(proposal_id,grant_id,grant_revision,request_hash,attribute_id,base_revision,payload,expires_at,created_at,storage_version,target_origin,target_vault_id,target_collection_id,target_record_id,target_kind,target_ciphertext_sha256,target_deleted,target_key_generation,target_owner_key_revision)\n      SELECT ?,cap.grant_id,cap.grant_revision,?,'owner_note',cap.base_revision,?,?,?,cap.storage_version,cap.target_origin,cap.target_vault_id,cap.target_collection_id,cap.target_record_id,cap.target_kind,cap.target_ciphertext_sha256,cap.target_deleted,cap.target_key_generation,cap.target_owner_key_revision\n      FROM agent_attribute_capability cap WHERE cap.grant_id=? AND cap.expires_at>=? AND ?>unixepoch()\n      AND EXISTS(SELECT 1 FROM agent_grant g\n JOIN agent_recipient_key rk ON rk.key_id=g.recipient_key_id AND rk.state='active'\n JOIN account_security a ON a.account_id=g.account_id AND a.active=1 AND a.epoch=g.owner_epoch\n JOIN credential c ON c.credential_id=g.credential_id AND c.account_id=g.account_id AND c.active=1\n WHERE g.revoked=0 AND g.expires_at>? AND g.expires_at>unixepoch()\n AND g.recipient_key_id=? AND g.resource=? AND g.encrypted_snapshot IS NOT NULL AND (g.storage_version=2 AND EXISTS(\n SELECT 1 FROM vault_owner_record_head h JOIN vault_owner_key_head k\n ON k.account_id=h.account_id AND k.vault_id=h.vault_id\n WHERE h.account_id=g.account_id AND h.vault_id=g.source_vault_id\n AND h.collection_id=g.source_collection_id AND h.record_id=g.source_record_id\n AND h.kind=g.source_kind AND h.revision=g.source_revision AND h.deleted=0 AND h.format_version=2\n AND h.ciphertext_sha256=g.source_ciphertext_sha256 AND h.key_generation=g.source_key_generation\n AND k.origin=g.source_origin AND k.key_generation=g.source_key_generation\n AND k.revision=g.source_owner_key_revision AND k.format_version=2\n AND k.suite='PRF-HKDF-SHA256-AES256GCM-v2')) AND g.storage_version=2 AND g.grant_id=cap.grant_id AND g.revision=? AND (g.storage_version=2 AND EXISTS(SELECT 1 FROM json_each(g.operations) WHERE value='propose')) AND (cap.grant_revision=g.revision AND cap.expires_at>unixepoch()\n    AND cap.expires_at<=g.expires_at) AND (cap.storage_version=2 AND EXISTS(SELECT 1 FROM vault_owner_key_head k\n    WHERE k.account_id=g.account_id AND k.vault_id=cap.target_vault_id AND k.origin=cap.target_origin\n      AND k.format_version=2 AND k.suite='PRF-HKDF-SHA256-AES256GCM-v2'\n      AND k.key_generation=cap.target_key_generation AND k.revision=cap.target_owner_key_revision)\n    AND ((cap.base_revision=0 AND cap.target_deleted=0 AND cap.target_ciphertext_sha256 IS NULL\n      AND NOT EXISTS(SELECT 1 FROM vault_owner_record_head h WHERE h.account_id=g.account_id\n        AND h.vault_id=cap.target_vault_id AND h.collection_id=cap.target_collection_id AND h.record_id=cap.target_record_id))\n    OR (cap.base_revision>0 AND EXISTS(SELECT 1 FROM vault_owner_record_head h WHERE h.account_id=g.account_id\n      AND h.vault_id=cap.target_vault_id AND h.collection_id=cap.target_collection_id AND h.record_id=cap.target_record_id\n      AND h.kind=cap.target_kind AND h.format_version=2 AND h.revision=cap.base_revision\n      AND h.key_generation=cap.target_key_generation AND h.deleted=cap.target_deleted\n      AND h.ciphertext_sha256 IS cap.target_ciphertext_sha256)))) AND (g.token_hash=? OR EXISTS(SELECT t.scopes FROM agent_oauth_token t\n  JOIN agent_oauth_client oc ON oc.client_id=t.client_id AND oc.active=1\n  WHERE t.token_hash=? AND t.grant_id=g.grant_id AND t.grant_revision=g.revision\n    AND t.resource=g.resource AND t.revoked=0 AND t.expires_at>unixepoch()\n    AND (t.authorization_details IS NULL OR (g.storage_version=2 AND t.authorization_details IS NOT NULL AND (json_array_length(t.authorization_details)=1 AND json_extract(t.authorization_details,'$[0].locations[0]')=g.resource\n    AND json_array_length(t.authorization_details,'$[0].locations')=1\n    AND json_array_length(t.authorization_details,'$[0].actions')=json_array_length(t.scopes)\n    AND NOT EXISTS(SELECT 1 FROM json_each(t.authorization_details,'$[0].actions') action\n      WHERE NOT EXISTS(SELECT 1 FROM json_each(t.scopes) scope WHERE scope.value=action.value)))\n    AND (json_extract(t.authorization_details,'$[0].storage_version')=2 AND json_extract(t.authorization_details,'$[0].type')='mikaki_agent_snapshot')\n    AND (json_extract(t.authorization_details,'$[0].document_id')=g.source_record_id AND json_array_length(g.document_ids)=1 AND json_extract(g.document_ids,'$[0]')=g.source_record_id)\n    AND (json_extract(t.authorization_details,'$[0].source.storage_version')=2 AND json_extract(t.authorization_details,'$[0].source.origin')=g.source_origin\n      AND json_extract(t.authorization_details,'$[0].source.owner_id')=g.account_id AND json_extract(t.authorization_details,'$[0].source.vault_id')=g.source_vault_id)\n    AND (json_extract(t.authorization_details,'$[0].source.collection_id')=g.source_collection_id\n      AND json_extract(t.authorization_details,'$[0].source.record_id')=g.source_record_id AND json_extract(t.authorization_details,'$[0].source.kind')=g.source_kind)\n    AND (json_extract(t.authorization_details,'$[0].source.revision')=g.source_revision\n      AND json_extract(t.authorization_details,'$[0].source.ciphertext_sha256')=g.source_ciphertext_sha256)\n    AND (json_extract(t.authorization_details,'$[0].authority.key_generation')=g.source_key_generation\n      AND json_extract(t.authorization_details,'$[0].authority.owner_key_revision')=g.source_owner_key_revision)))\n    AND NOT EXISTS(SELECT 1 FROM json_each(t.scopes) s\n      WHERE NOT EXISTS(SELECT 1 FROM json_each(g.operations) o WHERE o.value=s.value)))))\n      AND NOT EXISTS(SELECT 1 FROM agent_attribute_proposal WHERE proposal_id=?)\n      AND (SELECT count(*) FROM agent_attribute_proposal p WHERE p.grant_id=cap.grant_id AND p.state IN('pending','approved'))<20",
